V105_UNLOCK_AST_SHA256 = '80745099978a7ea9f75d17eb50370ccbb1ec59f751d677681d4b70935b12d18a'

V104_UNLOCK_AST_SHA256 = '2f5f91c5f263654fb766bb5069f8bcaa3d5bc515141c76c069dea47ab21cf79f'

V106_COUNTERATTACK_AST_SHA256 = '9ae2bb6e52b010ef75f9d5fb8ff1dba7938ed275755ce3b467769aeecc487e7f'

def expected_moved_ast_digest_v4200(root, symbol, legacy_digest, function_node):
    version=(Path(root)/'VERSION').read_text(encoding='utf-8').strip()
    # v106 and v107 retain the exact audited v105 Soul trial implementation;
    # the v106 raid-counterattack safeguard also remains byte-for-byte audited.
    # A new release number must not silently reinstate the v104 hash.
    if version in ('106.00.0', '107.00.0', '108.00.0', '109.00.0', '110.00.0', '111.00.0','112.00.0') and symbol == 'SessionSkillLearningMixin.enemy_counterattack':
        if legacy_digest != 'd87b3547c382fc27bc675b4e1bba6efe2f2aa17302aec76cf1fa80279fead176':
            raise AssertionError('Historyczny kontrakt kontry bossa ulegl zmianie.')
        body=ast.unparse(function_node)
        if 'cap_raid_incoming_v106' not in body or 'self.current_hp -= incoming' not in body:
            raise AssertionError('Brak ochrony realnej druzyny v106 w kontrataku.')
        return V106_COUNTERATTACK_AST_SHA256
    if version in ('107.00.0', '108.00.0', '109.00.0', '110.00.0', '111.00.0','112.00.0') and symbol == 'SessionIOAuthCharacterMixin.choose_existing_character':
        # The v107 rescue code deliberately differs from the v104 refactoring
        # baseline. Pin its full AST; do not disable the legacy audit.
        if legacy_digest != '83ac11323fe3aa427837c71c59098d896ba01932f8574d2aa998a9858bd7d570':
            raise AssertionError('Wymagana historyczna metoda wyboru postaci ulegla zmianie.')
        body=ast.unparse(function_node)
        if not all(token in body for token in (
            '_sb107_runtime_enabled()', 'raid_return_room_v107',
            'self.server.db.save_character(self.character)',
            'self.character.room_id = _old_room',
            'await self.send(',
        )):
            raise AssertionError('Brak bezpiecznego ratowania postaci v107 po wycofaniu rajdow.')
        return 'caf26d4221ff6ccac28c27563fd6c77f2523f1a0afca64d126923a742119eb58'
    # v108 modifies two extracted methods on purpose: the creator's route
    # back to races and the Giant Fortress portal dispatch. Preserve a strict
    # exact AST pin for both; never silently waive the refactoring ledger.
    if version in ('108.00.0', '109.00.0', '110.00.0', '111.00.0','112.00.0') and symbol == 'SessionIOAuthCharacterMixin.character_creator':
        if legacy_digest != '38585cde3f8bf660db1f0bb46de9d66e2dbae0b9dd345fa0c4116fe794962767':
            raise AssertionError('Kreator: nieoczekiwany historyczny wzorzec AST.')
        body=ast.unparse(function_node)
        if not all(token in body for token in ('wroc', 'wróć', 'rasy', 'Wybierz rasę', 'Wybierz klasę')):
            raise AssertionError('Kreator v108: brak powrotu do ras i wyboru klasy.')
        return '5bb2cffd976ef4f5564a57893e190a5c1ea23765953d64ba24cc50dcfea98116'
    if version in ('108.00.0', '109.00.0', '110.00.0', '111.00.0','112.00.0') and symbol == 'SessionDungeonProgressionMixin.use_crypt_portal':
        if legacy_digest != '373549c583e8c9fc998f1dda2a84d07abca3b48d44da0f1bbb7ef8a656b26551':
            raise AssertionError('Portale: nieoczekiwany historyczny wzorzec AST.')
        body=ast.unparse(function_node)
        if not all(token in body for token in ('giant_fortress_floor_number',
                'use_giant_fortress_portal_v10800', 'is_downed_v0371',
                'portal_requires_local_leader_v12811')):
            raise AssertionError('Portale v108: brak ochrony i routingu Twierdzy.')
        return '8a7c5c1672c3df266f7e908ce2ce3c585960392a5d3106eeea2f9a313ee3cbf0'
    if version not in ('105.00.0', '106.00.0', '107.00.0', '108.00.0', '109.00.0', '110.00.0', '111.00.0','112.00.0') or symbol != 'SessionSkillLearningMixin.unlock':
        return legacy_digest
    if legacy_digest != V104_UNLOCK_AST_SHA256:
        raise AssertionError('Historyczny fingerprint metody unlock z v104 zostal zmieniony.')
    body=ast.unparse(function_node)
    if not all(token in body for token in
               ('multi', 'SOUL_TRIAL_QUEST_IDS', '% 10 == 0', 'save_character')):
        raise AssertionError('Brak semantyki Prób co 10 Tierów i zapisu Duszy w v105.')
    return V105_UNLOCK_AST_SHA256

def read_factored_legacy_source_v410(file):
    file = Path(file)
    source = file.read_text(encoding='utf-8')
    # Native current sources carry their actual implementations directly.
    if '_sb410_bind(' not in source and '_sb420_topbind(' not in source:
        ast.parse(source, filename=str(file))
        return source
    path = str(file.resolve()).replace('\\','/')
    fragments = {}
    for symbol, (oldrel, newrel, required_hash, _) in SPLIT_SYMBOLS.items():
        if not path.endswith('/' + oldrel):
            continue
        helper = file.resolve().parents[len(oldrel.split('/'))-1] / newrel
        helper_src = helper.read_text(encoding='utf-8')
        tree = ast.parse(helper_src)
        match = [node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name==symbol]
        if len(match)!=1:
            raise AssertionError(('missing actual function body',symbol))
        authored = match[0]
        if sha256(ast.dump(authored,include_attributes=False).encode()).hexdigest()!=required_hash:
            raise AssertionError(('function AST changed',symbol))
        fragments[symbol] = '\n'.join(helper_src.splitlines()[authored.lineno-1:authored.end_lineno])+'\n'
    if not fragments:
        return source
    tree = ast.parse(source)
    lines=source.splitlines(keepends=True)
    replacements=[]
    for i,node in enumerate(tree.body):
        if not isinstance(node,ast.FunctionDef) or node.name not in fragments:
            continue
        nxt=tree.body[i+1]
        if not isinstance(nxt,ast.Assign) or not any(isinstance(t,ast.Name) and t.id==node.name for t in nxt.targets):
            raise AssertionError(('missing proper binding',node.name))
        if '_sb410_bind(' not in '\n'.join(lines[nxt.lineno-1:nxt.end_lineno]):
            raise AssertionError(('binding altered',node.name))
        replacements.append((node.lineno,nxt.end_lineno,fragments[node.name]))
    if len(replacements)!=len(fragments):
        raise AssertionError(('missing functions in source facade', len(replacements),len(fragments)))
    for start,end,body in sorted(replacements,reverse=True):
        lines[start-1:end]=[body]
    return ''.join(lines)

def read_actual_refactored_source_v4200(file):
    file=Path(file).resolve()
    code=read_factored_legacy_source_v410(file)
    if '_sb420_bind(' not in code and '_sb420_topbind(' not in code:
        ast.parse(code, filename=str(file))
        return code
    relevant={sym:desc for sym,desc in LEDGER.items() if str(file).replace('\\','/').endswith('/'+desc[0])}
    if not relevant:return code
    lines=code.splitlines(keepends=True)
    tree=ast.parse(code)
    replacements=[]
    actual=set()
    for symbol,(oldrel,newrel,digest,_) in relevant.items():
        origin=file.parents[len(oldrel.split('/'))-1]
        moved=(origin/newrel).read_text(encoding='utf8')
        node=next((n for n in ast.parse(moved).body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==symbol.rsplit('.',1)[-1]),None)
        if node is None:
            raise AssertionError(('module body missing',symbol))
        expected=expected_moved_ast_digest_v4200(origin, symbol, digest, node)
        if sha256(ast.dump(node,include_attributes=False).encode()).hexdigest()!=expected:
            raise AssertionError(('module body not identical',symbol))
        frag='\n'.join(moved.splitlines()[node.lineno-1:node.end_lineno])+'\n'
        if '.' in symbol:
            cls_name,name=symbol.split('.',1)
            cls=next((c for c in tree.body if isinstance(c,ast.ClassDef) and c.name==cls_name),None)
            if cls is None:raise AssertionError(('missing class',cls_name))
            stub=next((m for m in cls.body if isinstance(m,(ast.FunctionDef,ast.AsyncFunctionDef)) and m.name==name),None)
            if stub is None:raise AssertionError(('missing class method',symbol))
            if f'{cls_name}.{name} = _sb420_bind(' not in code:raise AssertionError(('missing live method binding',symbol))
            replacements.append((stub.lineno,stub.end_lineno,''.join('    '+line if line.strip() else line for line in frag.splitlines(keepends=True))))
        else:
            stub=next((n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==symbol),None)
            if stub is None:raise AssertionError(('missing source function',symbol))
            if f'{symbol} = _sb420_topbind(' not in code:raise AssertionError(('missing live function binding',symbol))
            replacements.append((stub.lineno,stub.end_lineno,frag))
        actual.add(symbol)
    if actual!=set(relevant):raise AssertionError(('missing audited extractions',relevant.keys()-actual))
    for start,end,text in sorted(replacements,reverse=True):lines[start-1:end]=[text]
    return ''.join(lines)


# Current-release PREDEPLOY source view.  Reads the physically shipped
# modules, verifies extracted AST through the canonical source contract above,
# and appends current world/quests fragments instead of retired v109 copies.
_CURRENT_SHARDS = {
    'data/items.py': ('data/catalog_parts/items_*.py',),
    'data/quests.py': ('world/quests/base_*.py',),
    'data/npcs.py': ('data/catalog_parts/npcs_*.py',),
    'data/mobs.py': ('data/catalog_parts/mobs_*.py',),
    'storage/db_inventory.py': ('storage/db_inventory_parts_v109/*.py',),
    'player/session_mixins/admin_tools.py': ('player/session_mixins/admin_tools_parts_v109/*.py',),
    'player/session_mixins/combat_survival.py': ('player/session_mixins/combat_survival_parts_v109/*.py',),
    'player/session_mixins/combat_damage.py': ('player/session_mixins/combat_damage_parts_v109/*.py',),
    'player/session_mixins/combat_rewards.py': ('player/session_mixins/combat_rewards_parts_v109/*.py',),
    'player/session_mixins/sales.py': ('player/session_mixins/sales_parts_v109/*.py',),
    'player/session_mixins/world_events_endgame.py': ('player/session_mixins/world_events_parts_v109/*.py',),
    'player/session_mixins/help.py': ('player/session_mixins/help_parts_v109/*.py',),
}

def read_actual_modular_source_current(file):
    root = Path(__file__).resolve().parents[1]
    file = Path(file).resolve(strict=True)
    try:
        relative = file.relative_to(root).as_posix()
    except ValueError as exc:
        raise AssertionError('Current source contract: source outside game tree') from exc
    code = read_actual_refactored_source_v4200(file)
    patterns = _CURRENT_SHARDS.get(relative, ())
    if relative == 'data/quests.py':
        expected = {f'base_{n:02d}.py' for n in range(1, 4)}
        actual = {p.name for p in (root/'world/quests').glob('base_*.py')}
        if actual != expected:
            raise AssertionError('Current quest source: missing or extra canonical shards')
    for glob in patterns:
        modules = sorted(root.glob(glob))
        if not modules:
            raise AssertionError('Current source contract: missing fragments '+glob)
        for part in modules:
            if part.is_symlink():
                raise AssertionError('Current source contract: symlinked fragment '+str(part))
            code += '\n'+part.read_text(encoding='utf-8-sig')
    return code
